static unsigned int nf_ct_generic_timeout __read_mostly = 600*HZ;



static inline struct nf_generic_net *generic_pernet(struct net *net)

{

	return &net->ct.nf_ct_proto.generic;

}



static bool generic_pkt_to_tuple(const struct sk_buff *skb,

				 unsigned int dataoff,

				 struct nf_conntrack_tuple *tuple)

{

	tuple->src.u.all = 0;

	tuple->dst.u.all = 0;



	return true;

}



static bool generic_invert_tuple(struct nf_conntrack_tuple *tuple,

				 const struct nf_conntrack_tuple *orig)

{

	tuple->src.u.all = 0;

	tuple->dst.u.all = 0;



	return true;

}



/* Print out the per-protocol part of the tuple. */

static int generic_print_tuple(struct seq_file *s,

			       const struct nf_conntrack_tuple *tuple)

{

	return 0;

}



static unsigned int *generic_get_timeouts(struct net *net)

{

	return &(generic_pernet(net)->timeout);

}



/* Returns verdict for packet, or -1 for invalid. */

static int generic_packet(struct nf_conn *ct,

			  const struct sk_buff *skb,

			  unsigned int dataoff,

			  enum ip_conntrack_info ctinfo,

			  u_int8_t pf,

			  unsigned int hooknum,

			  unsigned int *timeout)

{

	nf_ct_refresh_acct(ct, ctinfo, skb, *timeout);

	return NF_ACCEPT;

}



/* Called when a new connection for this protocol found. */

static bool generic_new(struct nf_conn *ct, const struct sk_buff *skb,

			unsigned int dataoff, unsigned int *timeouts)

{

	return true;

}



#if IS_ENABLED(CONFIG_NF_CT_NETLINK_TIMEOUT)



#include <linux/netfilter/nfnetlink.h>

#include <linux/netfilter/nfnetlink_cttimeout.h>



static int generic_timeout_nlattr_to_obj(struct nlattr *tb[],

					 struct net *net, void *data)

{

	unsigned int *timeout = data;

	struct nf_generic_net *gn = generic_pernet(net);



	if (tb[CTA_TIMEOUT_GENERIC_TIMEOUT])

		*timeout =

		    ntohl(nla_get_be32(tb[CTA_TIMEOUT_GENERIC_TIMEOUT])) * HZ;

	else {

		/* Set default generic timeout. */

		*timeout = gn->timeout;

	}



	return 0;

}



static int

generic_timeout_obj_to_nlattr(struct sk_buff *skb, const void *data)

{

	const unsigned int *timeout = data;



	if (nla_put_be32(skb, CTA_TIMEOUT_GENERIC_TIMEOUT, htonl(*timeout / HZ)))

		goto nla_put_failure;



	return 0;



nla_put_failure:

        return -ENOSPC;

}



static const struct nla_policy

generic_timeout_nla_policy[CTA_TIMEOUT_GENERIC_MAX+1] = {

	[CTA_TIMEOUT_GENERIC_TIMEOUT]	= { .type = NLA_U32 },

};

#endif /* CONFIG_NF_CT_NETLINK_TIMEOUT */



#ifdef CONFIG_SYSCTL

static struct ctl_table generic_sysctl_table[] = {

	{

		.procname	= "nf_conntrack_generic_timeout",

		.maxlen		= sizeof(unsigned int),

		.mode		= 0644,

		.proc_handler	= proc_dointvec_jiffies,

	},

	{ }

};

#ifdef CONFIG_NF_CONNTRACK_PROC_COMPAT

static struct ctl_table generic_compat_sysctl_table[] = {

	{

		.procname	= "ip_conntrack_generic_timeout",

		.maxlen		= sizeof(unsigned int),

		.mode		= 0644,

		.proc_handler	= proc_dointvec_jiffies,

	},

	{ }

};

#endif /* CONFIG_NF_CONNTRACK_PROC_COMPAT */

#endif /* CONFIG_SYSCTL */



static int generic_kmemdup_sysctl_table(struct nf_proto_net *pn,

					struct nf_generic_net *gn)

{

#ifdef CONFIG_SYSCTL

	pn->ctl_table = kmemdup(generic_sysctl_table,

				sizeof(generic_sysctl_table),

				GFP_KERNEL);

	if (!pn->ctl_table)

		return -ENOMEM;



	pn->ctl_table[0].data = &gn->timeout;

#endif

	return 0;

}



static int generic_kmemdup_compat_sysctl_table(struct nf_proto_net *pn,

					       struct nf_generic_net *gn)

{

#ifdef CONFIG_SYSCTL

#ifdef CONFIG_NF_CONNTRACK_PROC_COMPAT

	pn->ctl_compat_table = kmemdup(generic_compat_sysctl_table,

				       sizeof(generic_compat_sysctl_table),

				       GFP_KERNEL);

	if (!pn->ctl_compat_table)

		return -ENOMEM;



	pn->ctl_compat_table[0].data = &gn->timeout;

#endif

#endif

	return 0;

}



static int generic_init_net(struct net *net, u_int16_t proto)

{

	int ret;

	struct nf_generic_net *gn = generic_pernet(net);

	struct nf_proto_net *pn = &gn->pn;



	gn->timeout = nf_ct_generic_timeout;



	ret = generic_kmemdup_compat_sysctl_table(pn, gn);

	if (ret < 0)

		return ret;



	ret = generic_kmemdup_sysctl_table(pn, gn);

	if (ret < 0)

		nf_ct_kfree_compat_sysctl_table(pn);



	return ret;

}



static struct nf_proto_net *generic_get_net_proto(struct net *net)

{

	return &net->ct.nf_ct_proto.generic.pn;

}



